import{_ as d,o as a,c as r,a as e}from"./chunks/framework.Ld7uezS_.js";const c=JSON.parse('{"title":"7. 初起火灾处置知识","description":"","frontmatter":{},"headers":[],"relativePath":"theory/07-initial-fire.md","filePath":"theory/07-initial-fire.md","lastUpdated":1787288798000}'),h={name:"theory/07-initial-fire.md"};function i(l,t,o,n,s,b){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="_7-初起火灾处置知识" tabindex="-1">7. 初起火灾处置知识 <a class="header-anchor" href="#_7-初起火灾处置知识" aria-label="Permalink to &quot;7. 初起火灾处置知识&quot;">​</a></h1><h2 id="本章学习目标" tabindex="-1">本章学习目标 <a class="header-anchor" href="#本章学习目标" aria-label="Permalink to &quot;本章学习目标&quot;">​</a></h2><p>学完本章，你应该能判断“先救人还是先灭火”，知道报警、疏散、灭火器检查和现场保护的基本顺序，并能说明不同灭火剂的适用边界。</p><h2 id="一、处置总原则" tabindex="-1">一、处置总原则 <a class="header-anchor" href="#一、处置总原则" aria-label="Permalink to &quot;一、处置总原则&quot;">​</a></h2><p>发现火情后，不要把“拿灭火器”当成第一反应。基本顺序是：<strong>保护人员安全 → 立即报警和报告 → 组织疏散 → 在安全且经过培训的前提下处置初起火灾 → 火势扩大立即撤离 → 保护现场并配合调查</strong>。</p><p>操作员的职责是按预案和授权行动，不是冒险进入浓烟、高温、缺氧或有爆炸危险区域。</p><h2 id="二、灭火剂怎么选" tabindex="-1">二、灭火剂怎么选 <a class="header-anchor" href="#二、灭火剂怎么选" aria-label="Permalink to &quot;二、灭火剂怎么选&quot;">​</a></h2><table tabindex="0"><thead><tr><th>灭火剂/器材</th><th>适合的基本场景</th><th>主要风险或限制</th></tr></thead><tbody><tr><td>水</td><td>一般 A 类固体火灾的冷却</td><td>带电、油类、遇水反应物不能直接套用</td></tr><tr><td>泡沫</td><td>某些 A/B 类火灾，依产品和泡沫类型</td><td>水溶性液体要使用相适配的泡沫</td></tr><tr><td>ABC 干粉</td><td>常见固体、液体、气体及部分带电火灾</td><td>喷射后会残留粉末，设备保护和复燃要考虑</td></tr><tr><td>BC 干粉</td><td>主要用于 B/C 类及适用的带电场景</td><td>不把它当作 A 类固体火灾的通用答案</td></tr><tr><td>二氧化碳</td><td>某些 B/C/E 类和对残留敏感的场景</td><td>窒息、冻伤和复燃风险；不能用于所有火灾，密闭空间必须先考虑人员安全</td></tr><tr><td>洁净气体系统</td><td>设计用于特定封闭防护区</td><td>释放前后人员疏散、联动、延时和防护要求很重要</td></tr><tr><td>D 类专用灭火剂</td><td>适配特定金属火灾</td><td>必须按金属种类和产品铭牌选择，不能用普通灭火器替代</td></tr><tr><td>F 类专用灭火器/灭火系统</td><td>适配烹饪器具内油脂火灾</td><td>依据产品认证和现场配置使用，严禁直接泼水</td></tr></tbody></table><p>最终选择要看燃烧对象、是否带电、灭火器铭牌、现场环境和单位预案。</p><h2 id="三、先区分-报警、疏散、灭火、复燃观察-四件事" tabindex="-1">三、先区分“报警、疏散、灭火、复燃观察”四件事 <a class="header-anchor" href="#三、先区分-报警、疏散、灭火、复燃观察-四件事" aria-label="Permalink to &quot;三、先区分“报警、疏散、灭火、复燃观察”四件事&quot;">​</a></h2><p>初起火灾处置不是一个按钮动作，而是几项任务同时协作：</p><table tabindex="0"><thead><tr><th>任务</th><th>目的</th><th>典型动作</th><th>易错点</th></tr></thead><tbody><tr><td>报警/报告</td><td>让控制室、单位和消防救援力量获得信息</td><td>触发报警、拨打 119、说明地点和燃烧物</td><td>不能因为火小或有人处理就延迟报警</td></tr><tr><td>疏散/救人</td><td>先减少人员伤亡</td><td>引导人员远离烟气和危险区域，清点人员</td><td>不能为了取物或确认火势返回危险区</td></tr><tr><td>初起灭火</td><td>在安全条件满足时控制火势</td><td>选择适配器材，保持退路并按训练动作操作</td><td>不能把“会用灭火器”当成进入浓烟的许可</td></tr><tr><td>复燃观察/现场保护</td><td>防止再次起火并保留调查条件</td><td>观察、警戒、报告、保护痕迹</td><td>不能刚看不到火焰就清理、断电或离开</td></tr></tbody></table><p>这四件事有先后关系，也可能并行进行。人员安全和报警优先级高于追求“马上把火扑灭”。</p><h2 id="四、灭火器的检查、配置和报废边界" tabindex="-1">四、灭火器的检查、配置和报废边界 <a class="header-anchor" href="#四、灭火器的检查、配置和报废边界" aria-label="Permalink to &quot;四、灭火器的检查、配置和报废边界&quot;">​</a></h2><p>前面的“选择灭火剂”回答的是发生火情时怎么判断；平时还要会判断一具灭火器能不能作为可用器材。检查不是只看压力表，而是沿着“位置—类型—外观—部件—标识—记录”逐项核对：</p><table tabindex="0"><thead><tr><th>检查项</th><th>小白要看什么</th><th>发现异常意味着什么</th></tr></thead><tbody><tr><td>位置和可达性</td><td>是否在规定位置、无遮挡、标识清楚、取用路线通畅</td><td>即使器材本体完好，取不到也不能认为配置有效</td></tr><tr><td>类型和铭牌</td><td>灭火剂、适用火灾类别、使用方法和警示</td><td>类型不匹配时不能临时拿来“试一下”</td></tr><tr><td>瓶体和软管</td><td>是否锈蚀、变形、泄漏、破损或喷嘴堵塞</td><td>可能影响承压、喷射和人员安全，应隔离并按制度送检/维修</td></tr><tr><td>保险装置和铅封</td><td>保险销、铅封是否完整，是否有被使用痕迹</td><td>被使用过或封签异常，不能仅凭外观继续当作满状态器材</td></tr><tr><td>压力或状态指示</td><td>仅在该型号具有相应指示装置时，按铭牌和说明观察</td><td>指示异常不能自行充装或拆压，应交由授权单位处理</td></tr><tr><td>维修、检验和报废信息</td><td>日期、编号、状态标签是否清楚且未超出适用要求</td><td>不能凭“看起来新”推断仍在有效状态</td></tr></tbody></table><p>检查发现异常时，先记录编号、位置和缺陷，设置替代器材或临时防护并报告责任人；不要自行拆卸、泄压、充装或修改标签。具体维修周期、检验和报废判定必须以产品标识、现行标准、单位制度和有资质机构结论为准，本站不写死一个脱离型号和版本的统一年限。</p><h2 id="五、灭火器检查和使用" tabindex="-1">五、灭火器检查和使用 <a class="header-anchor" href="#五、灭火器检查和使用" aria-label="Permalink to &quot;五、灭火器检查和使用&quot;">​</a></h2><h3 id="先判断-烧的是什么-和-是否带电" tabindex="-1">先判断“烧的是什么”和“是否带电” <a class="header-anchor" href="#先判断-烧的是什么-和-是否带电" aria-label="Permalink to &quot;先判断“烧的是什么”和“是否带电”&quot;">​</a></h3><p>灭火器不是看到火就随便拿一具。零基础先按两个问题判断：<strong>正在燃烧的对象是什么？设备或线路是否可能带电？</strong></p><table tabindex="0"><thead><tr><th>看到的对象</th><th>先理解成什么</th><th>选择和安全边界</th></tr></thead><tbody><tr><td>木材、纸张、棉织物等普通固体</td><td>主要是 A 类对象</td><td>关注冷却和复燃；灭火器类型按现场配置和铭牌确认</td></tr><tr><td>汽油、酒精等液体或可熔化固体</td><td>主要是 B 类对象</td><td>防止液体飞溅和火势扩散，不用水柱盲目冲击液面</td></tr><tr><td>天然气、液化气等气体</td><td>主要是 C 类对象</td><td>重点是报警、人员安全和在安全条件下切断气源，不能只对着火焰喷射后离开</td></tr><tr><td>带电设备、线路</td><td>主要是 E 类对象</td><td>先按预案和授权断电，灭火剂必须适配带电风险，不湿手操作、不盲目靠近</td></tr><tr><td>油锅等烹饪油脂</td><td>主要是 F 类对象</td><td>不能泼水，防止高温油液飞溅扩大</td></tr><tr><td>镁、钠等金属</td><td>主要是 D 类对象</td><td>必须使用适配金属火灾的专用灭火剂，普通灭火器不能替代</td></tr></tbody></table><p>这个表用于建立判断顺序，不替代灭火器铭牌、单位预案和现场指挥。出现浓烟、高温、火势扩大、退路不清或无法判断燃烧物时，应立即撤离、报警并等待专业处置，不把“会使用灭火器”理解成可以冒险进入现场。</p><h3 id="使用前检查" tabindex="-1">使用前检查 <a class="header-anchor" href="#使用前检查" aria-label="Permalink to &quot;使用前检查&quot;">​</a></h3><p>确认灭火器类型适用，查看外观、铅封/保险销、喷管或喷嘴、压力指示（若该型号具备）、标识、维修和报废状态。发现泄漏、严重锈蚀、部件缺失或状态异常，不要把它当作有效器材使用。</p><h3 id="基本使用动作" tabindex="-1">基本使用动作 <a class="header-anchor" href="#基本使用动作" aria-label="Permalink to &quot;基本使用动作&quot;">​</a></h3><p>在安全前提下站在上风或侧上风方向，保持撤退路线：</p><ol><li>提起灭火器，确认火灾类别和退路；</li><li>拔出保险销；</li><li>握住喷管/喷嘴，对准火焰根部；</li><li>压下压把，左右扫射并逐步推进；</li><li>观察是否复燃，发现火势扩大立即撤离。</li></ol><p>这是训练口诀，不是允许无条件进入火场的授权。推车式灭火器、洁净气体系统和特殊灭火设备必须按产品说明书和专业培训操作。</p><h2 id="六、报警和疏散" tabindex="-1">六、报警和疏散 <a class="header-anchor" href="#六、报警和疏散" aria-label="Permalink to &quot;六、报警和疏散&quot;">​</a></h2><p>拨打 119 时说明起火地点、起火物质、火势情况、人员被困情况以及报警人联系方式，并按现场预案触发建筑火灾报警、通知相关人员和组织疏散。人员疏散应沿安全出口和疏散指示进行，不乘普通电梯，不返回取物；烟气较大时优先远离烟气、关闭防火门并沿安全疏散路径撤离。湿毛巾只能提供有限的短时辅助，不能过滤一氧化碳等有毒气体，也不能替代防烟楼梯、呼吸防护和专业救援。</p><p>如果出口被烟火封堵，应关闭门并利用通信、呼喊、灯光等方式发出求救信号，等待救援，不盲目穿越浓烟。</p><h2 id="七、场景练习" tabindex="-1">七、场景练习 <a class="header-anchor" href="#七、场景练习" aria-label="Permalink to &quot;七、场景练习&quot;">​</a></h2><p><strong>油锅起火</strong>：先关闭热源，在安全情况下使用适合的灭火器材或覆盖方式；直接泼水可能使高温油飞溅并扩大火势。</p><p><strong>配电箱冒烟</strong>：先报警、保持距离并按授权断电；灭火器和断电方式要符合带电火灾处置要求，不能用水直接喷射带电设备。</p><h2 id="八、火灾处置中的几个判断点" tabindex="-1">八、火灾处置中的几个判断点 <a class="header-anchor" href="#八、火灾处置中的几个判断点" aria-label="Permalink to &quot;八、火灾处置中的几个判断点&quot;">​</a></h2><h3 id="_1-什么时候可以尝试使用灭火器" tabindex="-1">1. 什么时候可以尝试使用灭火器 <a class="header-anchor" href="#_1-什么时候可以尝试使用灭火器" aria-label="Permalink to &quot;1. 什么时候可以尝试使用灭火器&quot;">​</a></h3><p>同时满足以下条件，才考虑在安全范围内使用适配器材：火势仍属初起、人员已报警或正在报警、灭火器适用、操作者受过训练、退路保持畅通、没有浓烟高温或爆炸危险。任何一个条件不满足，都应优先撤离、警戒并等待专业救援。</p><h3 id="_2-为什么不能把-火灭了-当成处置结束" tabindex="-1">2. 为什么不能把“火灭了”当成处置结束 <a class="header-anchor" href="#_2-为什么不能把-火灭了-当成处置结束" aria-label="Permalink to &quot;2. 为什么不能把“火灭了”当成处置结束&quot;">​</a></h3><p>还要观察是否复燃，保护现场，清点人员，保持消防设施和疏散条件可用，并按制度报告。涉及电气、油类、气体、可燃金属或密闭空间时，表面火焰消失不代表内部或周边危险已经消除。</p><h3 id="_3-现场保护记什么" tabindex="-1">3. 现场保护记什么 <a class="header-anchor" href="#_3-现场保护记什么" aria-label="Permalink to &quot;3. 现场保护记什么&quot;">​</a></h3><p>至少记录发现时间、地点、燃烧对象、报警和疏散情况、使用的器材、人员伤亡或被困信息、现场变化和移交对象。非经授权不要翻动、清理、冲洗或拆除可能影响原因调查的物品。</p><h2 id="九、自测" tabindex="-1">九、自测 <a class="header-anchor" href="#九、自测" aria-label="Permalink to &quot;九、自测&quot;">​</a></h2><ol><li>发现火灾时为什么不能只顾着寻找灭火器？</li><li>ABC 干粉和 BC 干粉的适用范围有什么差异？</li><li>使用灭火器时为什么要保留撤退路线？</li><li>火灾扑灭后为什么不能立即清理现场？</li><li>哪些条件不满足时应放弃近距离灭火并撤离？</li></ol><blockquote><p>参考：<a href="https://xfhyjd.119.gov.cn/zwossread/open1File/FirefightingSkillsAssessmentSystem/2025-11-13/4f0f6d863cf843228b5ce52030b59bb7/16193156145476990d82b-cb9d-43a7-a5f0-522abe3d1f8c%E5%9B%BD%E5%AE%B6%E8%81%8C%E4%B8%9A%E6%8A%80%E8%83%BD%E6%A0%87%E5%87%86%E2%80%94%E2%80%94%E6%B6%88%E9%98%B2%E8%AE%BE%E6%96%BD%E6%93%8D%E4%BD%9C%E5%91%98.pdf" target="_blank" rel="noreferrer">《消防设施操作员国家职业技能标准（2019年版）》</a> 2.2.6；灭火器具体检查要求应查产品标识、现行标准和单位制度。</p></blockquote>',44)])])}const u=d(h,[["render",i]]);export{c as __pageData,u as default};
